// API utility for uploading business hours
export async function uploadBusinessHours(data) {
  const response = await fetch("http://127.0.0.1:8000/api/v1/BussinessHours/create", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Authorization": `Bearer VIRoHdqUAtpklgKg`,
    },
    body: JSON.stringify(data),
  });
  if (!response.ok) {
    throw new Error("Failed to upload business hours");
  }
  return response.json();
}
